import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { ArrowDownLeft, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, BadgeCheck, Banknote, BookOpen, Building2, CalendarDays, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, ClipboardList, Download, FileCheck2, FileSpreadsheet, Files, FolderOpen, GraduationCap, History, Landmark, Layers3, ListChecks, LoaderCircle, LockKeyhole, MessageSquareText, MoreHorizontal, Package, Plus, PencilLine, RefreshCw, Search, Send, Settings2, ShieldCheck, Sparkles, Trash2, Upload, UserRound, Wallet, X } from 'lucide-react';
import Decimal from 'decimal.js';
import { version as appVersion } from '../package.json';
import type { Account, ChatMessage, ChatProposal, FixedAsset, Issue, JournalEntry, Mode, Operation, OperationType, ProcessingResult, Project, SourceDocument } from './core/types';
import { applyChatProposal, closeProject, createProject, createRevision, makeDemoProject, newId, parseProject, processProject, proposeChat, reopenProject, restoreRevision } from './core';
import { auditWorkbook, exportWorkbook, importFile, repairWorkbook, type WorkbookAudit } from './io';
import { backupProject, deleteProject, exportBytes, isDesktop, loadProjects, openExternal, saveProject, storageDescription } from './platform';
import { askChatGPT, connectChatGPT, disconnectChatGPT, getChatGPTStatus } from './desktop/ai';
import { exportToGoogleSheets } from './desktop/google';
import StudentWorkspace from './StudentWorkspace';

const DISCLAIMER = 'ContaEZ está diseñada exclusivamente para contabilidad y obligaciones fiscales de México, dentro de los regímenes, ejercicios y módulos indicados.';
const MODES: Record<Mode, { label: string; title: string; description: string; icon: typeof GraduationCap; tag: string }> = {
  student: { label: 'Prácticas universitarias', title: 'Aprende mientras resuelves', description: 'Analítico o perpetuos. Revisa tu práctica y entiende cada asiento.', icon: GraduationCap, tag: 'Para estudiantes' },
  business: { label: 'Empresa comercial', title: 'Tu empresa, en orden', description: 'Documentos, inventarios y cierres que puedes seguir hasta su origen.', icon: Building2, tag: 'Persona moral · 601' },
  individual: { label: 'Persona física', title: 'Menos pendientes, más claridad', description: 'Organiza cobros, pagos y papeles de trabajo de tu actividad.', icon: UserRound, tag: 'Actividad empresarial · 612' },
};
type Page = 'overview'|'documents'|'operations'|'inventory'|'review'|'reports'|'chat'|'rules'|'settings';
type ProfessionalMode = Exclude<Mode, 'student'>;
type SaveState = 'saving'|'saved'|'failed';
const PROFESSIONAL_MODES: ProfessionalMode[] = ['business','individual'];
const eligiblePeriod = (value: string) => /^202[56]-(?:0[1-9]|1[0-2])$/.test(value);
const validCalendarDate = (value: string) => /^\d{4}-\d{2}-\d{2}$/.test(value) &&
  !Number.isNaN(Date.parse(value+'T00:00:00Z')) && new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value;
const normalizeRate = (value:string) => {
  try{return new Decimal(value).toString();}catch{return value;}
};
const backupFile = (file: File) => /\.(contaez|json)$/i.test(file.name);
function rememberedGoogleClient(): string {
  try { return localStorage.getItem('contaez-google-client') || ''; } catch { return ''; }
}
function rememberGoogleClient(value: string) {
  try {
    if (/^[\w.-]+\.apps\.googleusercontent\.com$/.test(value.trim())) localStorage.setItem('contaez-google-client',value.trim());
    else localStorage.removeItem('contaez-google-client');
  } catch { /* Credentials can still be entered and used for this session. */ }
}
const NAV: { id: Page; label: string; icon: typeof Wallet }[] = [
  {id:'overview',label:'Resumen',icon:Wallet},{id:'documents',label:'Documentos',icon:Files},{id:'operations',label:'Movimientos',icon:ArrowDownLeft},{id:'inventory',label:'Inventario y activos',icon:Package},{id:'review',label:'Revisión',icon:ListChecks},{id:'reports',label:'Reportes',icon:FileSpreadsheet},{id:'chat',label:'Asistente',icon:MessageSquareText},
];
const OP_LABELS: Record<OperationType,string> = {purchase:'Compra',sale:'Venta',collection:'Cobro de factura',payment:'Pago a proveedor',purchase_return:'Devolución de compra',sale_return:'Devolución de venta',expense:'Gasto',contribution:'Aportación de capital',adjustment:'Ajuste manual'};
const currency=(v:string|number)=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',minimumFractionDigits:2}).format(Number(v)||0);
const dateLabel=(v:string)=>{const d=new Date(v+'T12:00:00');return Number.isNaN(d.valueOf())?v:d.toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'});};
const monthLabel=(v:string)=>{const d=new Date(v+'-15T12:00:00');return Number.isNaN(d.valueOf())?v:d.toLocaleDateString('es-MX',{month:'long',year:'numeric'});};
const positive=(v:string)=>{try{return new Decimal(v||0).gte(0)}catch{return false}};
const bytesBase64=(bytes:Uint8Array)=>{let s='';for(let i=0;i<bytes.length;i+=0x8000)s+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(s);};
const base64Bytes=(s:string)=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));

function AccountingWorkspace({initialMode,onBack}:{initialMode:ProfessionalMode;onBack:()=>void}){
  const [projects,setProjects]=useState<Project[]>([]),[activeId,setActiveId]=useState(''),[loaded,setLoaded]=useState(false),[page,setPage]=useState<Page>('overview');
  const [modal,setModal]=useState<null|'new'|'operation'|'opening'|'adjustment'|'account'|'asset'|'lot'|'history'>(null),[newMode,setNewMode]=useState<ProfessionalMode>(initialMode),[newName,setNewName]=useState(''),[newPeriod,setNewPeriod]=useState('2026-01');
  const [busy,setBusy]=useState(''),[toast,setToast]=useState<{text:string;error?:boolean}|null>(null),[saveStates,setSaveStates]=useState<Record<string,SaveState>>({}),[search,setSearch]=useState('');
  const [editingOperation,setEditingOperation]=useState<Operation|null>(null);
  const [audits,setAudits]=useState<Record<string,WorkbookAudit>>({}),[selectedReport,setSelectedReport]=useState('Balanza'),[chatText,setChatText]=useState(''),[aiQuestion,setAiQuestion]=useState(''),[aiAnswer,setAiAnswer]=useState('');
  const [ai,setAi]=useState<{connected:boolean;email?:string;model?:string}>({connected:false});
  const [googleId,setGoogleId]=useState(rememberedGoogleClient);
  const uploadRef=useRef<HTMLInputElement>(null),chatEnd=useRef<HTMLDivElement>(null),backupRef=useRef<HTMLInputElement>(null);
  const writing=useRef(new Map<string,Project>()),operationBusy=useRef(false);
  const project=projects.find(p=>p.id===activeId);
  const result=useMemo<ProcessingResult|null>(()=>project?processProject(project):null,[project]);
  const errors=result?.issues.filter(i=>i.severity==='error').length||0;
  const notices=result?.issues.filter(i=>i.severity==='warning').length||0;
  const flash=(text:string,error=false)=>setToast({text,error});
  useEffect(()=>{
    let active=true;
    loadProjects().then(all=>{
      if(!active)return;
      const checked:Project[]=[];
      let failed=0;
      for(const raw of all.filter(item=>item.mode==='business'||item.mode==='individual')){
        try{checked.push(parseProject(raw));}catch{failed++;}
      }
      setProjects(checked);
      setActiveId(checked.find(item=>item.mode===initialMode)?.id||'');
      if(failed)flash(`${failed} proyectos tienen un formato no compatible.`,true);
    }).catch(error=>{if(active)flash('No se pudieron abrir los proyectos: '+String(error),true);})
      .finally(()=>{if(active)setLoaded(true);});
    getChatGPTStatus().then(status=>{if(active)setAi(status);}).catch(()=>{});
    return()=>{active=false;};
  },[initialMode]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(null),6500);return()=>clearTimeout(t);},[toast]);
  useEffect(()=>{chatEnd.current?.scrollIntoView({behavior:'smooth',block:'nearest'});},[project?.chat.length]);
  const persist=(next:Project)=>{
    writing.current.set(next.id,next);
    setSaveStates(old=>({...old,[next.id]:'saving'}));
    return saveProject(next).then(()=>{
      if(writing.current.get(next.id)!==next)return;
      writing.current.delete(next.id);
      setSaveStates(old=>({...old,[next.id]:'saved'}));
    },error=>{
      if(writing.current.get(next.id)!==next)return;
      writing.current.delete(next.id);
      setSaveStates(old=>({...old,[next.id]:'failed'}));
      flash('No se pudo guardar «'+next.name+'». Reintenta o descarga un respaldo. '+String(error),true);
    });
  };
  const change=(next:Project)=>{
    const updated={...next,updatedAt:new Date().toISOString()};
    setProjects(prev=>prev.map(p=>p.id===updated.id?updated:p));
    void persist(updated);
  };
  const edit=(fn:(p:Project)=>Project,label?:string)=>{if(!project)return;if(project.closed){flash('Reabre el periodo desde Configuración para hacer cambios.',true);return;}const p=label?createRevision(project,label):project;change(fn(p));};
  const run=async(label:string,fn:()=>Promise<void>)=>{
    if(operationBusy.current)return;
    operationBusy.current=true;
    setBusy(label);
    try{await fn();}catch(error){flash(error instanceof Error?error.message:String(error),true);}
    finally{operationBusy.current=false;setBusy('');}
  };
  const selectProject=(id:string)=>{
    setActiveId(id);setPage('overview');setModal(null);setEditingOperation(null);
    setSearch('');setChatText('');setAiQuestion('');setAiAnswer('');
  };
  const addProject=async(p:Project)=>{
    await saveProject(p);
    setProjects(prev=>[p,...prev]);
    selectProject(p.id);
  };
  const handleCreate=()=>{
    if(!newName.trim()||!eligiblePeriod(newPeriod))return;
    return run('Creando proyecto',async()=>{
      await addProject(createProject(newMode,newName.trim(),newPeriod));
      flash('Proyecto creado. Empieza con tu apertura o importa documentos.');
    });
  };
  const importFiles=async(files:FileList|File[])=>{
    const selectedFiles=Array.from(files);
    if(!selectedFiles.length)return;
    if(selectedFiles.some(backupFile)){
      if(selectedFiles.length!==1){flash('Selecciona un respaldo por separado para abrirlo como proyecto.',true);return;}
      await run('Restaurando respaldo',async()=>{
        const data=JSON.parse(await selectedFiles[0].text());
        const candidate=parseProject(data?.project??data);
        if(candidate.mode==='student')throw new Error('Abre este respaldo desde Corregir una práctica Excel.');
        const name=candidate.name+' · respaldo';
        await addProject({...candidate,id:newId(),name,updatedAt:new Date().toISOString()});
        flash('Respaldo restaurado como un proyecto independiente.');
      });
      return;
    }
    if(!project)return;
    if(project.closed){flash('Reabre el periodo para importar.',true);return;}
    await run('Leyendo documentos',async()=>{
    let next=createRevision(project,'Antes de importar documentos');let count=0;const warnings:string[]=[];
    for(const file of selectedFiles){
      try{
        const imported=await importFile(file,next);
        for(const d of imported.documents){d.reviewNotes=imported.issues.map(i=>i.title+': '+i.detail+' '+i.suggestion);if(d.status!=='duplicate'){(d as SourceDocument&{contentBase64?:string}).contentBase64=bytesBase64(new Uint8Array(await file.arrayBuffer()));}}
        next={...next,documents:[...next.documents,...imported.documents],operations:[...next.operations,...imported.operations],manualEntries:[...next.manualEntries,...imported.entries],bankTransactions:[...next.bankTransactions,...imported.bankTransactions]};
        if(imported.audit){const doc=imported.documents[0];if(doc)setAudits(prev=>({...prev,[doc.id]:imported.audit!}));}
        if(imported.issues.length)warnings.push(imported.issues[0].title);count++;
      }catch(e){warnings.push(file.name+': '+(e instanceof Error?e.message:String(e)));}
    }
    if(count)change(next);
    setPage('documents');
    flash(`${count} archivo${count===1?'':'s'} procesado${count===1?'':'s'}. ${warnings.length?warnings.join(' · '):'Confirma los movimientos antes de procesarlos.'}`,count===0);
  });};
  const exportExcel=()=>run('Preparando Excel vinculado',async()=>{if(!project||!result)return;const data=await exportWorkbook(project,result);await exportBytes(data,project.name.replace(/[^\p{L}\p{N}\s_-]/gu,'').trim()+'__ContaEZ.xlsx');flash('Excel generado con fórmulas vinculadas y pendientes visibles.');});
  const submitChat=()=>{if(!project||!chatText.trim())return;const text=chatText.trim();const proposal=proposeChat(project,text);edit(p=>({...p,chat:[...p.chat,{id:newId(),role:'user',text,at:new Date().toISOString()},{id:newId(),role:'assistant',text:proposal.message,at:new Date().toISOString(),proposal}]}));setChatText('');};
  const confirmProposal=(messageId:string,proposal:ChatProposal)=>{if(!project)return;try{let p=applyChatProposal(createRevision(project,'Antes de aplicar indicación del chat'),proposal);p={...p,chat:p.chat.map(m=>m.id===messageId?{...m,text:m.text+'\nCambio confirmado y reportes actualizados.',proposal:undefined}:m)};change(p);flash('Información confirmada. Se actualizaron los cálculos.');}catch(e){flash(String(e),true)}};
  const inspectDocument=(d:SourceDocument)=>run('Revisando libro',async()=>{const content=(d as SourceDocument&{contentBase64?:string}).contentBase64;if(!content)throw new Error('Vuelve a importar el original para revisarlo.');const audit=await auditWorkbook(base64Bytes(content),d.name);setAudits(prev=>({...prev,[d.id]:audit}));flash('Revisión completada. Consulta los hallazgos de este documento.');});
  const repairDocument=(d:SourceDocument)=>run('Preparando copia revisada',async()=>{const content=(d as SourceDocument&{contentBase64?:string}).contentBase64;if(!content)throw new Error('Vuelve a importar el original para preparar la copia.');const repaired=await repairWorkbook(base64Bytes(content),d.name);await exportBytes(repaired.data,d.name.replace(/\.xlsx$/i,'')+'__revisada.xlsx');setAudits(prev=>({...prev,[d.id]:repaired.after}));flash(`${repaired.changes.length} correcciones comprobables. ${repaired.pending.length} observaciones pendientes. El original permanece intacto.`);});

  if(!loaded)return <div className="loading-screen"><Brand/><LoaderCircle className="spin"/><p>Abriendo tu espacio contable…</p></div>;

  const saveState=project?(saveStates[project.id]||'saved'):undefined;
  const goBack=()=>{
    const saving=projects.find(p=>saveStates[p.id]==='saving');
    if(saving){flash('Espera a que termine el guardado de «'+saving.name+'».');return;}
    const failed=projects.find(p=>saveStates[p.id]==='failed');
    if(failed){
      flash('Hay cambios sin guardar en «'+failed.name+'». Reintenta o descarga un respaldo antes de salir.',true);
      selectProject(failed.id);
      return;
    }
    onBack();
  };
  return <div className="app-shell">
    <div inert={!!busy||!!modal}>
    <aside className="sidebar">
      <Brand/>
      <button className="nav-item" onClick={goBack}><ArrowLeft size={18}/>Corregir una práctica Excel</button>
      <div className="project-switch"><span className="project-avatar">{project?(() => {const ModeIcon=MODES[project.mode].icon;return <ModeIcon size={20}/>})():<FolderOpen size={20}/>}</span><span><small>ESPACIO DE TRABAJO</small>{projects.length?<select aria-label="Proyecto activo" value={activeId} onChange={e=>selectProject(e.target.value)}>{!activeId&&<option value="">Elegir proyecto</option>}{PROFESSIONAL_MODES.map(mode=>projects.some(p=>p.mode===mode)&&<optgroup key={mode} label={MODES[mode].label}>{projects.filter(p=>p.mode===mode).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</optgroup>)}</select>:<strong>Tu primer proyecto</strong>}</span><button className="icon-button" title="Crear otro proyecto" onClick={()=>{setNewMode(project?.mode==='individual'?'individual':project?.mode==='business'?'business':initialMode);setNewName('');setModal('new')}}><Plus size={16}/></button></div>
      <div className="nav-caption">CONTABILIDAD</div>
      <nav>{NAV.map(n=><button key={n.id} className={'nav-item '+(page===n.id?'active':'')} disabled={!project} onClick={()=>setPage(n.id)}><n.icon size={18}/><span>{n.label}</span>{n.id==='review'&&errors>0&&<b className="nav-count">{errors}</b>}{n.id==='chat'&&<span className="new-label">Gratis</span>}</button>)}</nav>
      <div className="sidebar-bottom"><button className={'nav-item '+(page==='rules'?'active':'')} onClick={()=>setPage('rules')}><BookOpen size={18}/>Normativa mexicana</button><button className={'nav-item '+(page==='settings'?'active':'')} onClick={()=>setPage('settings')}><Settings2 size={18}/>Configuración</button><div className="local-note"><ShieldCheck size={17}/><span>Tu información, contigo<small>{storageDescription()}</small></span></div><button className="creator" onClick={()=>openExternal('https://www.instagram.com/betcover_ii/')}><span className="creator-avatar">b.</span><span>Creada por @betcover_ii<small>Hecha para México</small></span><ArrowUpRight size={14}/></button></div>
    </aside>
    <div className="app-body">
      <header className="topbar"><div className="breadcrumb">Mi espacio <ChevronRight size={14}/><span>{project?NAV.find(n=>n.id===page)?.label|| (page==='rules'?'Normativa':'Configuración'):'Bienvenida'}</span></div><div className="topbar-actions"><span className="mexico-pill"><i/> Solo México</span>{project&&<>{saveState==='failed'?<button className="button secondary compact" onClick={()=>void persist(project)} title="Reintentar guardado">Reintentar guardado</button>:<span className="save-state" role="status"><CheckCheck size={14}/>{saveState==='saving'?'Guardando…':'Guardado'}</span>}<button className="icon-button" title="Historial de revisiones" onClick={()=>setModal('history')}><History size={18}/></button><button className="button primary compact" onClick={()=>setModal('operation')} disabled={project.closed}><Plus size={16}/>Movimiento</button></>}</div></header>
      <main>
        {!project&&page!=='rules'&&page!=='settings'?<>
          <div className="welcome"><span className="eyebrow"><span className="tiny-square"/> CONTABILIDAD MEXICANA, SIN COMPLICACIONES</span><h1>Tu contabilidad,<br/><em>en orden.</em></h1><p>Un lugar para entender tus números, resolver tus prácticas<br className="desktop-break"/> y trabajar con confianza. Gratis, desde tu computadora.</p><div className="welcome-proof"><span><Check size={15}/> Sin suscripción obligatoria</span><span><Check size={15}/> Excel vinculado</span><span><Check size={15}/> Datos locales</span></div></div>
          <div className="section-heading"><div><h2>¿Qué vamos a trabajar?</h2><p>Elige una modalidad. Puedes tener varios proyectos.</p></div><span className="text-muted">01 / EMPEZAR</span></div>
          <div className="mode-grid">{PROFESSIONAL_MODES.map((mode,i)=>{const m=MODES[mode];return <button className="mode-card" key={mode} onClick={()=>{setNewMode(mode);setNewName('');setModal('new')}}><div className={'mode-icon mode-'+mode}><m.icon size={27}/></div><span className="mode-tag">{m.tag}</span><h3>{m.label}</h3><p>{m.description}</p><span className="mode-action">Crear proyecto <ArrowRight size={17}/></span><span className="mode-number">0{i+1}</span></button>;})}</div>
          <div className="intro-bottom"><div><span className="round-icon"><Sparkles size={20}/></span><div><h3>Explora un ejemplo o restaura un respaldo</h3><p>El ejemplo usa datos ficticios de la modalidad que elegiste.</p></div></div><div className="button-group"><button className="button secondary" onClick={()=>backupRef.current?.click()}><FolderOpen size={16}/>Restaurar respaldo</button><button className="button secondary" onClick={()=>void run('Abriendo ejemplo',()=>addProject(makeDemoProject(initialMode)))}>Explorar un ejemplo <ArrowRight size={16}/></button></div></div>
          <div className="jurisdiction-note"><Landmark size={17}/><p>{DISCLAIMER}</p></div>
        </>:project&&page==='overview'&&result?<>
          <PageTitle eyebrow={MODES[project.mode].label} title={project.name} subtitle="Cada cifra tiene un origen. Cada cambio, una explicación." action={<button className="period-button" onClick={()=>setPage('settings')}><CalendarDays size={17}/>{monthLabel(project.period)}<ChevronDown size={14}/></button>}/>
          {project.notes.some(n=>n.includes("datos ficticios"))&&<div className="demo-label"><Sparkles size={14}/>Ejemplo con datos ficticios · puedes crear tu propio proyecto</div>}<div className="stats-grid"><Stat label="Ventas netas" value={result.incomeStatement.revenue} icon={ArrowUpRight} accent="green" caption="Operaciones confirmadas del periodo"/><Stat label="Costos y gastos" value={new Decimal(result.incomeStatement.costOfSales).plus(result.incomeStatement.expenses).toFixed(2)} icon={ArrowDownLeft} caption="Costo de ventas y gastos registrados"/><Stat label="Resultado del periodo" value={result.incomeStatement.profit} icon={Wallet} accent="green" caption="Ingresos menos costos y gastos"/><Stat label="Saldo en activos" value={result.balanceSheet.assets} icon={Landmark} caption="Según el registro contable"/></div>
          <div className={'review-banner '+(errors?'attention':'')}><span className="banner-icon">{errors?<ClipboardList size={22}/>:<FileCheck2 size={22}/>}</span><div><strong>{errors?`${errors} pendientes antes de terminar`:project.operations.length?'Revisa el alcance de tus resultados':'Tu proyecto está listo para comenzar'}</strong><p>{errors?'Encontramos información o registros que necesitan tu atención.':notices?`${notices} observaciones para revisar. Los resultados dependen de los documentos incluidos.`:project.operations.length?'Los reportes reflejan las operaciones confirmadas. Comprueba que el periodo incluya todos sus documentos.':'Importa documentos o registra tu apertura. La ausencia de movimientos no acredita una contabilidad completa.'}</p></div><button className="text-button" onClick={()=>setPage('review')}>Ver revisión <ArrowRight size={16}/></button></div>
          <div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><h2>Movimientos recientes</h2><p>Tu actividad contable, en un solo lugar.</p></div><button className="text-button" onClick={()=>setPage('operations')}>Ver todos <ArrowRight size={15}/></button></div>{project.operations.length?<div className="activity-list">{project.operations.slice(-5).reverse().map(op=><div className="activity-row" key={op.id}><span className={'activity-icon '+(['sale','collection','contribution'].includes(op.type)?'income':'expense')}><ArrowDownLeft size={18}/></span><div><strong>{op.description}</strong><small>{OP_LABELS[op.type]} · {dateLabel(op.date)}</small></div><div className="activity-amount">{currency(op.amount)}<small>{op.confirmed?'Confirmado':'Por confirmar'}</small></div></div>)}</div>:<Empty icon={ArrowDownLeft} title="Todavía no hay movimientos" text="Registra una operación o importa los documentos del periodo." action={<button className="button secondary" onClick={()=>setModal('operation')}><Plus size={15}/>Registrar movimiento</button>}/>}</section><section className="panel composition-panel"><div className="panel-heading"><div><h2>Una vista del balance</h2><p>Activos, pasivos y capital.</p></div></div><div className="balance-graphic"><div className="balance-donut" style={{'--slice':`${Math.min(100,Math.max(0,Number(result.balanceSheet.liabilities)/(Number(result.balanceSheet.assets)||1)*100))}%`} as React.CSSProperties}><div><small>ACTIVOS</small><strong>{currency(result.balanceSheet.assets)}</strong><span>MXN</span></div></div></div><div className="legend"><span><i style={{background:'#c5ae75'}}/>Pasivos<strong>{currency(result.balanceSheet.liabilities)}</strong></span><span><i/>Capital y resultado<strong>{currency(new Decimal(result.balanceSheet.equity).plus(result.balanceSheet.profit).toFixed(2))}</strong></span></div><div className="balance-check"><span>Diferencia contable</span><b className={new Decimal(result.balanceSheet.difference).isZero()?'':'red-text'}>{currency(result.balanceSheet.difference)}</b></div></section></div>
          <section className="bottom-grid"><button className="quick-panel" onClick={()=>uploadRef.current?.click()}><span className="quick-icon"><Upload size={23}/></span><div><h3>De tus documentos a tus libros</h3><p>Importa Excel, XML, PDF o estados de cuenta.</p></div><ArrowRight size={19}/></button><button className="quick-panel chat-panel" onClick={()=>setPage('chat')}><span className="quick-icon"><MessageSquareText size={24}/></span><div><h3>Cuéntale más a tu proyecto</h3><p>Completa datos y aclara pendientes en el chat.</p></div><ArrowRight size={19}/></button></section>
        </>:project&&page==='documents'?<>
          <PageTitle eyebrow="EL ORIGEN DE TUS NÚMEROS" title="Documentos" subtitle="Conserva los originales y revisa la información antes de incorporarla." action={<button className="button primary" onClick={()=>uploadRef.current?.click()}><Plus size={17}/>Importar documentos</button>}/>
          <div className="drop-zone" role="button" tabIndex={0} onClick={()=>uploadRef.current?.click()} onKeyDown={e=>{if(e.key==='Enter')uploadRef.current?.click()}} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();void importFiles(e.dataTransfer.files)}}><span><Upload size={25}/></span><h3>Arrastra tus archivos aquí</h3><p>Excel, CFDI XML, CSV, PDF e imágenes · Los originales se conservan</p><small>También puedes hacer clic para elegir archivos</small></div>
          <section className="panel"><div className="panel-heading"><h2>Archivos de este proyecto <span className="count-pill">{project.documents.length}</span></h2><span className="text-muted">Guardados en este equipo</span></div>{project.documents.length?<div className="document-list">{project.documents.map(d=><div className="document-item" key={d.id}><div className="document-row"><span className="file-icon"><FileSpreadsheet size={23}/></span><div className="document-name"><strong>{d.name}</strong><small>{d.uuid?`UUID: ${d.uuid}`:new Date(d.importedAt).toLocaleString('es-MX')}</small></div><Status kind={d.status==='confirmed'?'success':d.status==='duplicate'?'muted':'warning'}>{d.status==='confirmed'?'Revisado':d.status==='duplicate'?'Duplicado':'Por revisar'}</Status>{/\.xlsx$/i.test(d.name)&&<><button className="button secondary compact" onClick={()=>void inspectDocument(d)}>Revisar libro</button><button className="button secondary compact" onClick={()=>void repairDocument(d)}><Download size={14}/>Copia revisada</button></>}<button className="icon-button" title="Confirmar revisión del documento" onClick={()=>edit(p=>({...p,documents:p.documents.map(x=>x.id===d.id?{...x,status:'confirmed'}:x)}),'Confirmar documento')}><Check size={18}/></button></div>{(d.text||d.reviewNotes?.length)&&<details className="document-preview"><summary>Información extraída y observaciones</summary>{d.reviewNotes?.map((n,i)=><p key={i}>{n}</p>)}{d.text&&<pre>{d.text.slice(0,18000)}</pre>}</details>}{audits[d.id]&&<div className="document-audit"><div className="audit-summary"><b>Diagnóstico del libro</b><span>{audits[d.id].formulaCount} fórmulas · {audits[d.id].findings.length} hallazgos</span></div>{audits[d.id].findings.slice(0,10).map((f,i)=><div key={i} className="audit-finding"><Status kind={f.severity==='error'?'danger':'warning'}>{f.sheet}{f.cell?'!'+f.cell:''}</Status><span>{f.message}<small>{f.suggestion}</small></span></div>)}{audits[d.id].findings.length>10&&<p className="small-note">El informe completo se incluye en la copia revisada.</p>}{!audits[d.id].findings.length&&<p>Sin errores detectados en las comprobaciones disponibles. No equivale a una auditoría contable completa.</p>}</div>}</div>)}</div>:<Empty icon={Files} title="El proyecto todavía no tiene documentos" text="Los XML facilitan la captura; las imágenes y documentos ambiguos necesitan confirmación."/>}</section>
        </>:project&&page==='operations'?<>
          <PageTitle eyebrow="REGISTRO CONTABLE" title="Movimientos" subtitle="Importes de captura sin IVA. Confirma los datos para incorporarlos a tus reportes." action={<div className="button-group"><button className="button secondary" onClick={()=>setModal('opening')}><Landmark size={16}/>Apertura</button><button className="button secondary" onClick={()=>setModal('adjustment')}><BookOpen size={16}/>Asiento manual</button><button className="button primary" onClick={()=>setModal('operation')}><Plus size={17}/>Nuevo movimiento</button></div>}/>
          <div className="table-toolbar"><div className="search-field"><Search size={16}/><input aria-label="Buscar movimientos" placeholder="Buscar concepto, fecha o tipo…" value={search} onChange={e=>setSearch(e.target.value)}/></div><span className="text-muted">{project.operations.filter(o=>o.confirmed).length} confirmados de {project.operations.length}</span></div>
          <section className="panel table-wrap"><table><thead><tr><th>FECHA</th><th>CONCEPTO</th><th>TIPO</th><th className="number">BASE</th><th>ESTADO</th><th/></tr></thead><tbody>{project.operations.filter(o=>(o.description+' '+o.date+' '+OP_LABELS[o.type]).toLowerCase().includes(search.toLowerCase())).map(op=><tr key={op.id}><td>{dateLabel(op.date)}</td><td><strong>{op.description}</strong><small>{op.productId?`${op.productId} · ${op.quantity||'—'} unidades`:op.paymentMethod==='credit'?'A crédito':op.paymentMethod==='cash'?'Efectivo':'Bancos'}</small></td><td>{OP_LABELS[op.type]}</td><td className="number">{currency(op.amount)}</td><td><Status kind={op.confirmed?'success':'warning'}>{op.confirmed?'Confirmado':'Por confirmar'}</Status></td><td><div className="row-actions"><button className="icon-button" title="Editar movimiento" onClick={()=>{setEditingOperation(op);setModal('operation')}}><PencilLine size={15}/></button>{!op.confirmed&&<button className="icon-button" title="Confirmar movimiento" onClick={()=>edit(p=>({...p,operations:p.operations.map(x=>x.id===op.id?{...x,confirmed:true}:x)}),'Confirmar movimiento')}><Check size={17}/></button>}<button className="icon-button" title="Eliminar movimiento" onClick={()=>edit(p=>({...p,operations:p.operations.filter(x=>x.id!==op.id)}),'Eliminar movimiento')}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table>{!project.operations.length&&<Empty icon={ArrowDownLeft} title="Comienza por tu primera operación" text="Puedes registrar compras, ventas, cobros, pagos y gastos, o importar tus documentos." action={<button className="button secondary" onClick={()=>setModal('operation')}>Registrar movimiento</button>}/>}</section>
          {project.manualEntries.length>0&&<section className="panel"><div className="panel-heading"><h2>Apertura y asientos manuales</h2></div><div className="activity-list">{project.manualEntries.map(e=><div className="activity-row" key={e.id}><Landmark size={19}/><div><strong>{e.concept}</strong><small>{dateLabel(e.date)} · {e.lines.length} movimientos</small></div><span>{currency(e.lines.reduce((a,l)=>new Decimal(a).plus(l.debit||0).toString(),'0'))}</span><button className="icon-button" title="Eliminar asiento" onClick={()=>edit(p=>({...p,manualEntries:p.manualEntries.filter(x=>x.id!==e.id)}),'Eliminar asiento')}><Trash2 size={15}/></button></div>)}</div></section>}
        </>:project&&page==='inventory'&&result?<>
          <PageTitle eyebrow="CONTROL DE EXISTENCIAS" title="Inventario y activos" subtitle="Cantidades, capas de costo y activos con un origen verificable." action={<div className="button-group"><button className="button secondary" onClick={()=>setModal('asset')}><Plus size={16}/>Activo</button><button className="button primary" onClick={()=>setModal('lot')}><Plus size={16}/>Inventario inicial</button></div>}/>
          <div className="method-box"><div><Package size={23}/><span><strong>{project.inventorySystem==='analytical'?'Método analítico':'Inventarios perpetuos'}</strong><small>{project.valuation==='fifo'?'PEPS · primeras entradas, primeras salidas':'Costo promedio móvil'}</small></span></div><button className="text-button" onClick={()=>setPage('settings')}>Configurar método <Settings2 size={15}/></button></div>
          {project.inventoryInitial.length>0&&<section className="panel"><div className="panel-heading"><h2>Existencias iniciales</h2><p>Registra también su valor en el asiento de apertura.</p></div><div className="table-wrap"><table><thead><tr><th>ARTÍCULO</th><th className="number">UNIDADES</th><th className="number">COSTO UNITARIO</th><th className="number">VALOR</th></tr></thead><tbody>{project.inventoryInitial.map(l=><tr key={l.id}><td>{l.productId}</td><td className="number">{l.quantity}</td><td className="number">{currency(l.unitCost)}</td><td className="number">{currency(new Decimal(l.quantity).mul(l.unitCost).toString())}</td></tr>)}</tbody></table></div></section>}
          <section className="panel"><div className="panel-heading"><h2>Tarjeta de almacén</h2><span className="text-muted">{project.valuation==='fifo'?'PEPS':'Promedio móvil'}</span></div><div className="table-wrap"><table><thead><tr><th>FECHA / CONCEPTO</th><th>ARTÍCULO</th><th className="number">ENTRADAS</th><th className="number">SALIDAS</th><th className="number">EXISTENCIA</th><th className="number">COSTO SALIDA</th><th className="number">SALDO</th></tr></thead><tbody>{result.inventory.map((r,i)=><tr key={r.operationId+'-'+i}><td>{dateLabel(r.date)}<small>{r.description}</small></td><td>{r.productId}</td><td className="number">{r.incoming}</td><td className="number">{r.outgoing}</td><td className="number">{r.quantity}</td><td className="number">{currency(r.cost)}</td><td className="number">{currency(r.balance)}</td></tr>)}</tbody></table>{!result.inventory.length&&<Empty icon={Package} title="Sin movimientos de inventario" text="Agrega un artículo en las compras y ventas para seguir sus cantidades y costos."/>}</div></section>
          <section className="panel"><div className="panel-heading"><h2>Activos y periodificación</h2><button className="text-button" onClick={()=>setModal('asset')}>Agregar activo <Plus size={15}/></button></div>{project.assets.length?<div className="activity-list">{project.assets.map(a=><div className="activity-row" key={a.id}><Layers3 size={20}/><div><strong>{a.name}</strong><small>{a.type==='amortization'?'Amortización':'Depreciación'} · {a.usefulLifeMonths} meses · desde {dateLabel(a.startDate)}</small></div><b>{currency(a.cost)}</b><button className="icon-button" title="Eliminar activo" onClick={()=>edit(p=>({...p,assets:p.assets.filter(x=>x.id!==a.id)}),'Eliminar activo')}><Trash2 size={15}/></button></div>)}</div>:<div className="panel-body small-note">Registra costo, valor residual, vida útil y fecha de inicio. El cálculo contable se mantiene separado de las deducciones fiscales.</div>}</section>
        </>:project&&page==='review'&&result?<>
          <PageTitle eyebrow="ENTIENDE ANTES DE CORREGIR" title="Revisión del proyecto" subtitle="Una balanza que cuadra es el comienzo. Revisamos también cobertura, periodos e inventarios." action={<button className="button secondary" onClick={()=>setPage('chat')}><MessageSquareText size={17}/>Aclarar en el chat</button>}/>
          <div className="review-stats"><div><span className="status-dot danger"/><strong>{errors}</strong><span>Por resolver</span></div><div><span className="status-dot warning"/><strong>{notices}</strong><span>Observaciones</span></div><div><span className="status-dot success"/><strong>{project.operations.filter(o=>o.confirmed).length}</strong><span>Operaciones confirmadas</span></div></div>
          <section className="panel issue-list">{result.issues.map(issue=><IssueCard key={issue.id} issue={issue} onHelp={()=>{setPage('chat');setChatText('Quiero aclarar: '+issue.title)}}/>)}{!result.issues.length&&<Empty icon={ShieldCheck} title="Sin incidencias en las reglas disponibles" text="Este resultado cubre los datos incorporados y las comprobaciones admitidas. Confirma que incluiste toda la información del periodo."/>}</section>
          <div className="jurisdiction-note"><CircleHelp size={18}/><p>Los libros importados tienen su propio diagnóstico en Documentos. Resolver una fórmula no confirma que todas las operaciones del ejercicio estén incluidas.</p></div>
        </>:project&&page==='reports'&&result?<>
          <PageTitle eyebrow="DE LOS REGISTROS A LAS DECISIONES" title="Reportes" subtitle="Resultados derivados de las operaciones confirmadas. Descarga el trabajo y sus pendientes." action={<button className="button primary" onClick={()=>void exportExcel()}><ArrowDownToLine size={17}/>Descargar Excel</button>}/>
          <div className="report-tabs">{['Balanza','Resultados','Balance','Diario','Fiscal','Bancos'].map(t=><button className={selectedReport===t?'selected':''} key={t} onClick={()=>setSelectedReport(t)}>{t}</button>)}</div>
          {selectedReport==='Balanza'?<section className="panel table-wrap"><div className="panel-heading"><h2>Balanza de comprobación</h2><span className="text-muted">{monthLabel(project.period)} · MXN</span></div><table><thead><tr><th>CUENTA</th><th>CONCEPTO</th><th className="number">DEBE</th><th className="number">HABER</th><th className="number">SALDO DEUDOR</th><th className="number">SALDO ACREEDOR</th></tr></thead><tbody>{result.trialBalance.filter(r=>![r.debit,r.credit,r.balanceDebit,r.balanceCredit].every(v=>new Decimal(v).isZero())).map(r=><tr key={r.account.code}><td className="account-code">{r.account.code}</td><td>{r.account.name}</td><td className="number">{currency(r.debit)}</td><td className="number">{currency(r.credit)}</td><td className="number">{currency(r.balanceDebit)}</td><td className="number">{currency(r.balanceCredit)}</td></tr>)}</tbody><tfoot><tr><td colSpan={2}>Sumas</td>{(['debit','credit','balanceDebit','balanceCredit'] as const).map(k=><td className="number" key={k}>{currency(result.trialBalance.reduce((a,r)=>new Decimal(a).plus(r[k]).toString(),'0'))}</td>)}</tr></tfoot></table></section>:selectedReport==='Resultados'?<FinancialStatement title="Estado de resultados" project={project} rows={[['Ventas netas',result.incomeStatement.revenue],['Costo de ventas',result.incomeStatement.costOfSales],['Gastos de operación',result.incomeStatement.expenses],['Resultado del periodo',result.incomeStatement.profit]]}/>:selectedReport==='Balance'?<FinancialStatement title="Estado de situación financiera" project={project} rows={[['Activo',result.balanceSheet.assets],['Pasivo',result.balanceSheet.liabilities],['Capital',result.balanceSheet.equity],['Resultado del periodo',result.balanceSheet.profit],['Diferencia',result.balanceSheet.difference]]}/>:selectedReport==='Diario'?<section className="panel ledger-list"><div className="panel-heading"><h2>Libro diario</h2><span>{result.entries.length} asientos</span></div>{result.entries.map(e=><div className="journal-block" key={e.id}><div><b>{e.concept}</b><span>{dateLabel(e.date)}</span></div><table><tbody>{e.lines.map(l=><tr key={l.id}><td className="account-code">{l.accountCode}</td><td>{project.accounts.find(a=>a.code===l.accountCode)?.name||'Cuenta no encontrada'}</td><td className="number">{currency(l.debit)}</td><td className="number">{currency(l.credit)}</td></tr>)}</tbody></table></div>)}</section>:selectedReport==='Fiscal'?<>
            <div className="fiscal-note"><Landmark size={20}/><div><strong>Papeles de trabajo · {project.regime==='601'?'Persona moral, régimen general':project.regime==='612'?'Persona física, actividad empresarial/profesional':'Práctica académica'}</strong><p>Cálculo preliminar según datos confirmados. Las diferencias fiscales y obligaciones requieren revisión.</p></div><Status kind={result.taxes.status==='incomplete'?'warning':'muted'}>{result.taxes.status==='incomplete'?'Datos pendientes':'Borrador'}</Status></div>
            <div className="stats-grid three"><Stat label="IVA cobrado" value={result.taxes.vatCollected} icon={ArrowDownLeft} caption="Según cobros registrados"/><Stat label="IVA pagado" value={result.taxes.vatPaid} icon={ArrowUpRight} caption="Según pagos registrados"/><Stat label="Diferencia de IVA" value={result.taxes.vatDue} icon={Landmark} caption="Consulta retenciones y observaciones"/></div>
            <FinancialStatement title="ISR provisional · papel de trabajo" project={project} rows={[['Ingresos considerados',result.taxes.taxableRevenue],['Deducciones consideradas',result.taxes.deductions],['Base de cálculo',result.taxes.isrBase],['ISR provisional',result.taxes.isr]]}/><section className="panel panel-body"><h3>Datos y alcance del cálculo</h3>{result.taxes.notes.map((n,i)=><p className="small-note" key={i}>{n}</p>)}<button className="button secondary" onClick={()=>setPage('settings')}>Completar datos fiscales <ArrowRight size={15}/></button></section>
          </>:<><FinancialStatement title="Conciliación bancaria" project={project} rows={[['Saldo contable de bancos',result.bankReconciliation.ledgerBalance],['Movimientos de estado de cuenta',result.bankReconciliation.statementBalance],['Diferencia por conciliar',result.bankReconciliation.difference]]}/><div className="small-note">{result.bankReconciliation.unmatchedCount} movimientos sin vincular. Importa tu estado bancario CSV con fecha, descripción e importe. El saldo del extracto se debe revisar con su apertura.</div><section className="panel table-wrap"><table><thead><tr><th>FECHA</th><th>MOVIMIENTO BANCARIO</th><th className="number">IMPORTE</th><th>RELACIONAR CON</th></tr></thead><tbody>{project.bankTransactions.map(b=><tr key={b.id}><td>{dateLabel(b.date)}</td><td>{b.description}</td><td className="number">{currency(b.amount)}</td><td><select aria-label={'Relacionar '+b.description} value={b.matchedOperationId||''} onChange={e=>edit(p=>({...p,bankTransactions:p.bankTransactions.map(x=>x.id===b.id?{...x,matchedOperationId:e.target.value||undefined}:x)}),'Relacionar movimiento bancario')}><option value="">Por relacionar</option>{project.operations.map(o=><option key={o.id} value={o.id}>{o.description} · {currency(o.amount)}</option>)}</select></td></tr>)}</tbody></table></section></>}
          <div className="export-options"><button className="button secondary" onClick={()=>void run('Creando Google Sheets',async()=>{const url=await exportToGoogleSheets(project,result,googleId);await openExternal(url);flash('Hoja creada en tu cuenta de Google.');})}><FileSpreadsheet size={17}/>Abrir en Google Sheets</button><button className="button secondary" onClick={()=>void run('Guardando respaldo',async()=>{await backupProject(project);flash(isDesktop()?'Respaldo guardado.':'Se solicitó la descarga del respaldo. Revisa Descargas.');})}><FolderOpen size={17}/>Respaldo del proyecto</button><span className="small-note">CONTPAQi requiere un perfil de producto y versión validado. Consulta su estado en Configuración.</span></div>
        </>:project&&page==='chat'?<>
          <PageTitle eyebrow="INFORMACIÓN QUE COMPLETA TU TRABAJO" title="Asistente del proyecto" subtitle="Agrega datos, aclara pendientes y entiende tus registros. El chat guiado es gratis." action={<Status kind="success"><span className="status-dot success"/>Sin IA obligatoria</Status>}/>
          <div className="chat-layout"><section className="panel chat-window"><div className="chat-messages"><div className="chat-bubble assistant"><span className="chat-avatar"><MessageSquareText size={18}/></span><div><strong>Un poco más de contexto ayuda mucho.</strong><p>Puedes decirme el periodo, el método o una operación nueva. Te mostraré la propuesta antes de modificar los datos.</p></div></div>{project.chat.map(m=><div className={'chat-bubble '+m.role} key={m.id}>{m.role==='assistant'&&<span className="chat-avatar"><MessageSquareText size={17}/></span>}<div><p>{m.text}</p>{m.proposal&&m.proposal.kind!=='clarification'&&<button className="button primary compact" onClick={()=>confirmProposal(m.id,m.proposal!)}><Check size={14}/>Confirmar información</button>}{m.proposal?.kind==='clarification'&&<button className="button secondary compact" onClick={()=>setModal('operation')}>Abrir captura de movimiento</button>}<small>{new Date(m.at).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})}</small></div></div>)}<div ref={chatEnd}/></div><div className="chat-examples">{['El periodo es enero de 2026','Usar método analítico','Cambiar a PEPS'].map(t=><button key={t} onClick={()=>setChatText(t)}>{t}</button>)}</div><div className="chat-composer"><textarea aria-label="Mensaje al asistente" placeholder="Escribe la información que quieres agregar…" value={chatText} onChange={e=>setChatText(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();submitChat()}}}/><button className="icon-button attach" title="Adjuntar documentos" onClick={()=>uploadRef.current?.click()}><Plus size={21}/></button><button className="send-button" title="Enviar mensaje" onClick={submitChat} disabled={!chatText.trim()||project.closed}><Send size={18}/></button></div><p className="chat-footnote">Solo los datos confirmados entran al cálculo. Cada cambio queda en el historial.</p></section><aside className="chat-side"><section className="panel panel-body"><span className="ai-badge"><Sparkles size={19}/></span><h3>Preguntas más abiertas</h3><p>Si lo deseas, consulta con tu propio ChatGPT. Tú eliges qué información compartir.</p><Status kind={ai.connected?'success':'muted'}>{ai.connected?'Cuenta conectada':'Opcional · cuenta propia'}</Status>{!ai.connected?<button className="button secondary full" onClick={()=>void run('Conectando ChatGPT',async()=>{setAi(await connectChatGPT());flash('ChatGPT conectado con tu cuenta.');})}>Continuar con ChatGPT <ArrowUpRight size={14}/></button>:<><textarea aria-label="Pregunta a ChatGPT" placeholder="¿Qué significa esta observación?" value={aiQuestion} onChange={e=>setAiQuestion(e.target.value)}/><button className="button primary full" disabled={!aiQuestion.trim()} onClick={()=>void run('Consultando tu ChatGPT',async()=>{const context=JSON.stringify({jurisdiction:'MX',period:project.period,mode:project.mode,inventorySystem:project.inventorySystem,issues:result?.issues.map(i=>({code:i.code,title:i.title,detail:i.detail,suggestion:i.suggestion}))});setAiAnswer(await askChatGPT(aiQuestion,context));})}>Consultar con contexto de revisión</button><small>Se enviarán periodo, modalidad y observaciones. Los archivos originales no se adjuntan.</small></>}{aiAnswer&&<div className="ai-answer">{aiAnswer}</div>}</section><section className="context-card"><h4><ClipboardList size={16}/>Contexto confirmado</h4><dl><dt>Periodo</dt><dd>{monthLabel(project.period)}</dd><dt>Método</dt><dd>{project.inventorySystem==='analytical'?'Analítico':'Perpetuos'}</dd><dt>Valuación</dt><dd>{project.valuation==='fifo'?'PEPS':'Promedio móvil'}</dd><dt>Documentos</dt><dd>{project.documents.length}</dd></dl>{project.notes.length>0&&<div className="project-notes">{project.notes.map((n,i)=><p key={i}>{n}</p>)}</div>}</section></aside></div>
        </>:page==='rules'?<RulesPage/>:page==='settings'?<>
          <PageTitle eyebrow="TU ESPACIO, A TU MANERA" title="Configuración" subtitle="Los cambios de periodo y método conservan una revisión del proyecto."/>
          {project&&<SettingsPanel project={project} onChange={change} onEdit={edit} onOpening={()=>setModal('opening')} onAccount={()=>setModal('account')} onHistory={()=>setModal('history')} onDelete={()=>void run('Eliminando proyecto',async()=>{await deleteProject(project.id);const remaining=projects.filter(p=>p.id!==project.id);setProjects(remaining);setActiveId(remaining[0]?.id||'');setPage('overview');flash('Proyecto eliminado de este equipo.');})} onFlash={flash} result={result!}/>}
          <section className="panel panel-body"><h2>Conexiones opcionales</h2><div className="settings-row"><div><strong>Google Sheets</strong><p>Usa un cliente OAuth de escritorio registrado en tu proyecto de Google. La autorización se realiza en el navegador. Un JSON de credenciales se mantiene en memoria hasta que el almacén nativo lo proteja.</p></div><label className="field"><span>Client ID o JSON OAuth de escritorio</span><input value={googleId} placeholder="…apps.googleusercontent.com" onChange={e=>{const value=e.target.value;setGoogleId(value);rememberGoogleClient(value);}}/></label></div><div className="settings-row"><div><strong>Tu ChatGPT</strong><p>{ai.connected?ai.email||'Conectado con tu cuenta':'El cálculo contable funciona sin esta conexión.'}</p></div>{ai.connected?<div className="button-group"><button className="button secondary" onClick={()=>void openExternal('https://chatgpt.com/settings/usage')}>Administrar uso</button><button className="button secondary" onClick={()=>void run('Desconectando ChatGPT',async()=>{try{await disconnectChatGPT();}finally{setAi(await getChatGPTStatus());}})}>Desconectar</button></div>:<button className="button secondary" onClick={()=>void run('Conectando ChatGPT',async()=>setAi(await connectChatGPT()))}>Continuar con ChatGPT</button>}</div><div className="settings-row"><div><strong>CONTPAQi</strong><p>La exportación de pólizas se habilita al validar un perfil del producto y versión de destino con una empresa de prueba.</p></div><Status kind="warning">Validación externa pendiente</Status></div></section>
          <section className="panel panel-body about-panel"><Brand/><h3>Contabilidad clara. Hecha para México.</h3><p>ContaEZ {appVersion} · Gratuita y de código abierto · GPL-3.0</p><p>{DISCLAIMER}</p><div className="about-links"><a href="https://www.instagram.com/betcover_ii/" target="_blank" rel="noreferrer">Creada por @betcover_ii <ArrowUpRight size={15}/></a><a href="mailto:gallardoquirozd4@gmail.com">gallardoquirozd4@gmail.com</a></div><small>Los cálculos y revisiones cubren los módulos implementados. Revisa el alcance y los pendientes antes de usar resultados profesionales.</small></section>
        </>:null}
        <footer className="app-footer"><span>ContaEZ <i/> Contabilidad para México</span><span>Gratis, con o sin IA.</span></footer>
      </main>
    </div>
    <input ref={uploadRef} className="visually-hidden" type="file" multiple accept=".xlsx,.xml,.csv,.pdf,.png,.jpg,.jpeg,.webp,.json,.contaez" aria-label="Seleccionar documentos" onChange={e=>{if(e.target.files)void importFiles(e.target.files);e.target.value=''}}/>
    <input ref={backupRef} hidden type="file" accept=".json,.contaez" aria-label="Seleccionar respaldo" onChange={e=>{if(e.target.files)void importFiles(e.target.files);e.target.value=''}}/>
    </div>
    {modal==='new'&&<Modal title="Un proyecto nuevo" subtitle="Elige cómo quieres trabajar y define el periodo." onClose={()=>setModal(null)}><div className="mode-selector">{PROFESSIONAL_MODES.map(m=><button key={m} className={newMode===m?'selected':''} aria-pressed={newMode===m} onClick={()=>setNewMode(m)}>{(() => {const I=MODES[m].icon;return <I size={22}/>})()}<span>{MODES[m].label}</span></button>)}</div><label className="field"><span>Nombre del proyecto</span><input autoFocus placeholder="Ej. Comercializadora del Pacífico" value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')void handleCreate()}}/></label><label className="field"><span>Periodo</span><input type="month" min="2025-01" max="2026-12" value={newPeriod} onChange={e=>setNewPeriod(e.target.value)}/></label><p className="small-note">México · MXN · {newMode==='business'?'Régimen general de personas morales':'Actividad empresarial y profesional'}</p><div className="modal-actions"><button className="button secondary" disabled={!!busy} onClick={()=>void run('Abriendo ejemplo',()=>addProject(makeDemoProject(newMode)))}>Ver ejemplo de esta modalidad</button><button className="button primary" disabled={!!busy||!newName.trim()||!eligiblePeriod(newPeriod)} onClick={()=>void handleCreate()}>Crear proyecto <ArrowRight size={16}/></button></div></Modal>}
    {modal==='operation'&&project&&<OperationModal project={project} initial={editingOperation} onClose={()=>{setModal(null);setEditingOperation(null)}} onSave={op=>{edit(p=>({...p,operations:editingOperation?p.operations.map(x=>x.id===op.id?op:x):[...p.operations,op]}),'Registrar '+OP_LABELS[op.type]);setModal(null);setEditingOperation(null);flash('Movimiento registrado y reportes actualizados.');}}/>}
    {modal==='adjustment'&&project&&<OpeningModal project={project} kind="adjustment" onClose={()=>setModal(null)} onSave={entry=>{edit(p=>({...p,manualEntries:[...p.manualEntries,entry]}),'Registrar asiento manual');setModal(null);flash('Asiento manual registrado y revisado por el motor.');}}/>}
    {modal==='opening'&&project&&<OpeningModal project={project} onClose={()=>setModal(null)} onSave={entry=>{edit(p=>({...p,manualEntries:[...p.manualEntries.filter(e=>e.kind!=='opening'),entry],taxConfig:{...p.taxConfig,openingBalancesConfirmed:true}}),'Registrar apertura');setModal(null);flash('Apertura registrada.');}}/>}
    {modal==='account'&&project&&<AccountModal accounts={project.accounts} onClose={()=>setModal(null)} onSave={a=>{edit(p=>({...p,accounts:[...p.accounts,a]}),'Agregar cuenta');setModal(null);flash('Cuenta agregada al catálogo.');}}/>}
    {modal==='asset'&&project&&<AssetModal project={project} onClose={()=>setModal(null)} onSave={a=>{edit(p=>({...p,assets:[...p.assets,a]}),'Registrar activo');setModal(null);flash('Activo registrado. Revisa que su adquisición esté en los asientos.');}}/>}
    {modal==='lot'&&project&&<LotModal project={project} onClose={()=>setModal(null)} onSave={lot=>{edit(p=>({...p,inventoryInitial:[...p.inventoryInitial,lot]}),'Registrar inventario inicial');setModal(null);flash('Existencias iniciales registradas. Comprueba su valor en la apertura.');}}/>}
    {modal==='history'&&project&&<Modal title="Historial de revisiones" subtitle="Restaura un estado anterior conservando el registro de la recuperación." onClose={()=>setModal(null)}>{project.revisions.length?<div className="revision-list">{project.revisions.slice().reverse().map(r=><div className="settings-row" key={r.id}><div><strong>{r.label}</strong><p>{new Date(r.at).toLocaleString('es-MX')}</p></div><button className="button secondary compact" onClick={()=>{const restored=restoreRevision(project,r.id);change(restored.id===project.id?restored:{...restored,id:project.id,name:project.name});setModal(null);flash('Revisión restaurada.');}}>Restaurar</button></div>)}</div>:<Empty icon={History} title="Aún no hay revisiones" text="Las importaciones y cambios importantes guardarán un estado anterior."/>}</Modal>}
    {busy&&<div className="busy-overlay" role="status"><LoaderCircle className="spin" size={23}/><span>{busy}…</span></div>}
    {toast&&<div className={'toast '+(toast.error?'error':'')} role="status">{toast.error?<CircleHelp size={19}/>:<Check size={19}/>}<span>{toast.text}</span><button className="icon-button" onClick={()=>setToast(null)} title="Cerrar aviso"><X size={16}/></button></div>}
  </div>;
}

function Brand(){return <div className="brand"><span className="brand-symbol"><i/><i/><i/></span><span>Conta<span>EZ</span><small>CONTABILIDAD MEXICANA</small></span></div>}
function PageTitle({eyebrow,title,subtitle,action}:{eyebrow:string;title:string;subtitle:string;action?:ReactNode}){return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function Stat({label,value,icon:Icon,caption,accent}:{label:string;value:string;icon:typeof Wallet;caption:string;accent?:string}){return <section className={'stat-card '+(accent||'')}><div><span>{label}</span><Icon size={17}/></div><strong>{currency(value)}</strong><small>{caption}</small></section>}
function Status({kind,children}:{kind:'success'|'warning'|'danger'|'muted';children:ReactNode}){return <span className={'status '+kind}>{children}</span>}
function Empty({icon:Icon,title,text,action}:{icon:typeof Wallet;title:string;text:string;action?:ReactNode}){return <div className="empty-state"><span><Icon size={25}/></span><h3>{title}</h3><p>{text}</p>{action}</div>}
function IssueCard({issue,onHelp}:{issue:Issue;onHelp:()=>void}){return <article className={'issue-card '+issue.severity}><span className="issue-icon">{issue.severity==='error'?<ClipboardList size={21}/>:<CircleHelp size={21}/>}</span><div><div><h3>{issue.title}</h3><Status kind={issue.severity==='error'?'danger':issue.severity==='warning'?'warning':'muted'}>{issue.severity==='error'?'Por resolver':issue.severity==='warning'?'Observación':'Información'}</Status></div>{issue.location&&<small className="issue-location">{issue.location}</small>}<p>{issue.detail}</p><div className="issue-suggestion"><strong>Cómo resolverlo</strong><p>{issue.suggestion}</p></div></div><button className="icon-button" title="Aclarar esta observación en el chat" onClick={onHelp}><MessageSquareText size={18}/></button></article>}
function FinancialStatement({title,project,rows}:{title:string;project:Project;rows:[string,string|null][]}){return <section className="panel statement"><div className="statement-heading"><span className="eyebrow">{project.name}</span><h2>{title}</h2><p>{monthLabel(project.period)} · Pesos mexicanos</p></div>{rows.map(([label,value],i)=><div className={'statement-row '+(i===rows.length-1?'total':'')} key={label}><span>{label}</span><strong>{value===null?'Faltan datos':currency(value)}</strong></div>)}</section>}
function Modal({title,subtitle,children,onClose}:{title:string;subtitle:string;children:ReactNode;onClose:()=>void}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="modal" role="dialog" aria-modal="true" aria-label={title}><button className="icon-button modal-close" title="Cerrar" onClick={onClose}><X size={21}/></button><h2>{title}</h2><p className="modal-subtitle">{subtitle}</p>{children}</section></div>}

function OperationModal({project,initial,onClose,onSave}:{project:Project;initial?:Operation|null;onClose:()=>void;onSave:(o:Operation)=>void}){
  const [type,setType]=useState<OperationType>(initial?.type||'expense');
  const [description,setDescription]=useState(initial?.description||'');
  const [date,setDate]=useState(initial?.date||project.period+'-01');
  const [amount,setAmount]=useState(initial?.amount||'');
  const [vat,setVat]=useState(normalizeRate(initial?.vatRate||'0.16'));
  const [payment,setPayment]=useState<Operation['paymentMethod']>(initial?.paymentMethod||'bank');
  const [account,setAccount]=useState(initial?.accountCode||'601.01');
  const [product,setProduct]=useState(initial?.productId||'');
  const [quantity,setQuantity]=useState(initial?.quantity||'');
  const [cost,setCost]=useState(initial?.unitCost||'');
  const [related,setRelated]=useState(initial?.relatedOperationId||'');
  const [deductible,setDeductible]=useState(initial?.taxDeductible===undefined?'':String(initial.taxDeductible));
  const [error,setError]=useState('');
  const referenceOnly=initial?.referenceOnly===true;
  const inventory=['purchase','purchase_return'].includes(type)||(['sale','sale_return'].includes(type)&&(project.mode!=='individual'||!!product));
  const settlement=type==='collection'||type==='payment';
  const linked=settlement||type==='purchase_return'||type==='sale_return';
  const fiscalReview=project.mode==='individual'&&['expense','purchase','purchase_return','payment'].includes(type);
  const relatedOptions=project.operations.filter(o=>{
    if(o.id===initial?.id||!o.confirmed)return false;
    if(settlement&&o.paymentMethod!=='credit')return false;
    if(!settlement&&o.referenceOnly)return false;
    return type==='collection'||type==='sale_return'?o.type==='sale':o.type==='purchase'||(type==='payment'&&o.type==='expense');
  });
  const total=(()=>{
    try{return new Decimal(amount||0).mul(new Decimal(1).plus(vat)).toFixed(2);}
    catch{return null;}
  })();
  const submit=()=>{
    try{
      if(!description.trim())throw new Error('Escribe un concepto.');
      const subtotal=new Decimal(amount||0);
      if(!subtotal.isFinite()||subtotal.lt('0.01'))throw new Error('Indica una base de al menos $0.01.');
      if(!validCalendarDate(date)||(!referenceOnly&&!date.startsWith(project.period+'-'))||(referenceOnly&&date>=project.period+'-01')) {
        throw new Error(referenceOnly?'La fecha del saldo anterior debe preceder al periodo del proyecto.':'La fecha debe estar dentro del periodo del proyecto.');
      }
      if(linked&&!relatedOptions.some(op=>op.id===related))throw new Error('Relaciona una operación original compatible.');
      if(inventory&&!referenceOnly){
        const units=new Decimal(quantity||0);
        if(!product.trim()||!units.isFinite()||!units.gt(0))throw new Error('Indica artículo y una cantidad válida.');
      }
      if(referenceOnly&&new Decimal(initial!.openingOutstandingBase??0).gt(subtotal))throw new Error('La base debe cubrir el saldo inicial pendiente.');
      onSave({
        ...initial,id:initial?.id||newId(),type,description:description.trim(),date,amount:subtotal.toFixed(2),
        vatRate:vat,paymentMethod:payment,accountCode:type==='expense'?account:initial?.accountCode,
        productId:inventory||referenceOnly?product.trim()||undefined:undefined,
        quantity:inventory||referenceOnly?quantity||undefined:undefined,unitCost:type==='purchase'?cost||undefined:undefined,
        relatedOperationId:linked?related:undefined,sourceIds:initial?.sourceIds||[],confirmed:true,
        taxDeductible:fiscalReview?deductible===''?undefined:deductible==='true':initial?.taxDeductible
      });
    }catch(e){setError(e instanceof Error?e.message:String(e));}
  };
  return <Modal title={initial?'Editar movimiento':'Registrar movimiento'} subtitle="Captura el subtotal sin IVA y verifica el total antes de confirmar." onClose={onClose}>
    {referenceOnly&&<p className="small-note">Saldo de una operación anterior. Conserva su relación con los cobros o pagos de este periodo.</p>}
    <div className="form-grid">
      <label className="field"><span>Tipo de operación</span><select value={type} disabled={referenceOnly} onChange={e=>{
        const nextType=e.target.value as OperationType;
        setType(nextType);setRelated('');
        if(nextType==='contribution')setVat('0');
        if((nextType==='collection'||nextType==='payment')&&payment==='credit')setPayment('bank');
      }}>{Object.entries(OP_LABELS).filter(([k])=>k!=='adjustment'||k===type).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label>
      <label className="field"><span>Fecha</span><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label>
      <label className="field span-two"><span>Concepto</span><input autoFocus placeholder="Ej. Compra de mercancía a proveedor" value={description} onChange={e=>setDescription(e.target.value)}/></label>
      <label className="field"><span>Subtotal sin IVA</span><input type="number" min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></label>
      <label className="field"><span>IVA</span><select disabled={type==='contribution'} value={vat} onChange={e=>setVat(e.target.value)}>
        <option value="0.16">16 %</option><option value="0.08">8 % · verificar elegibilidad</option><option value="0">0 % · verificar tratamiento</option>
        {!['0.16','0.08','0'].includes(vat)&&<option value={vat}>Tasa registrada ({vat})</option>}
      </select></label>
      <label className="field"><span>Forma de pago</span><select value={payment} disabled={referenceOnly} onChange={e=>setPayment(e.target.value as Operation['paymentMethod'])}>
        <option value="bank">Bancos</option><option value="cash">Efectivo</option><option value="credit" disabled={settlement}>A crédito</option>
      </select></label>
      {type==='expense'&&<label className="field"><span>Cuenta del gasto</span><select value={account} onChange={e=>setAccount(e.target.value)}>{project.accounts.filter(a=>a.type==='expense').map(a=><option key={a.code} value={a.code}>{a.code} · {a.name}</option>)}</select></label>}
      {inventory&&!referenceOnly&&<>
        <label className="field"><span>Artículo / clave</span><input value={product} placeholder="Ej. OMEGA" onChange={e=>setProduct(e.target.value)}/></label>
        <label className="field"><span>Cantidad</span><input type="number" min="0.000001" step="any" value={quantity} onChange={e=>setQuantity(e.target.value)}/></label>
        {type==='purchase'&&<label className="field"><span>Costo unitario sin IVA</span><input type="number" min="0" step="any" value={cost} placeholder="Base ÷ cantidad" onChange={e=>setCost(e.target.value)}/></label>}
      </>}
      {linked&&<label className="field span-two"><span>Operación original</span><select value={related} onChange={e=>{
        const op=relatedOptions.find(item=>item.id===e.target.value);
        setRelated(e.target.value);
        if(op){setProduct(op.productId||'');setVat(normalizeRate(op.vatRate));}
      }}><option value="">Selecciona la factura u operación</option>{relatedOptions.map(o=><option key={o.id} value={o.id}>{o.description} · {dateLabel(o.date)} · {currency(o.amount)}</option>)}</select></label>}
    </div>
    {fiscalReview&&<label className="field"><span>Deducción fiscal para ISR</span><select value={deductible} onChange={e=>setDeductible(e.target.value)}>
      <option value="">Por confirmar</option><option value="true">Deducible, con documentación revisada</option><option value="false">No deducible</option>
    </select></label>}
    <div className="form-total"><span>Total con IVA</span><strong>{total===null?'Por verificar':currency(total)}</strong></div>
    {error&&<p className="form-error" role="alert">{error}</p>}
    <div className="modal-actions"><button className="button secondary" onClick={onClose}>Cancelar</button><button className="button primary" onClick={submit}><Check size={16}/>Confirmar movimiento</button></div>
  </Modal>;
}

function OpeningModal({project,kind='opening',onClose,onSave}:{project:Project;kind?:'opening'|'adjustment';onClose:()=>void;onSave:(e:JournalEntry)=>void}){
 const existing=kind==='opening'?project.manualEntries.find(e=>e.kind==='opening'):undefined;const [concept,setConcept]=useState(''),[entryDate,setEntryDate]=useState(project.period+'-01');const [rows,setRows]=useState(existing?.lines.map(l=>({...l}))||[{id:newId(),accountCode:'102.01',debit:'',credit:''},{id:newId(),accountCode:'301.01',debit:'',credit:''}]);
 const debit=rows.reduce((a,l)=>a.plus(l.debit||0),new Decimal(0)),credit=rows.reduce((a,l)=>a.plus(l.credit||0),new Decimal(0));
 const valid=debit.eq(credit)&&rows.every(r=>positive(r.debit)&&positive(r.credit)&&!(Number(r.debit)>0&&Number(r.credit)>0));
 return <Modal title={kind==='opening'?'Saldos de apertura':'Asiento manual'} subtitle={kind==='opening'?'Incluye las cuentas que existían al inicio. Una apertura en ceros también debe confirmarse expresamente.':'Registra ajustes, adquisiciones de activos o provisiones con su evidencia y criterio confirmado.'} onClose={onClose}>{kind==='adjustment'&&<div className="form-grid"><label className="field"><span>Concepto del asiento</span><input value={concept} onChange={e=>setConcept(e.target.value)}/></label><label className="field"><span>Fecha del asiento</span><input type="date" value={entryDate} onChange={e=>setEntryDate(e.target.value)}/></label></div>}<div className="opening-grid"><div className="opening-labels"><span>Cuenta</span><span>Debe</span><span>Haber</span><span/></div>{rows.map((r,i)=><div key={r.id}><select aria-label={'Cuenta apertura '+(i+1)} value={r.accountCode} onChange={e=>setRows(v=>v.map((x,j)=>j===i?{...x,accountCode:e.target.value}:x))}>{project.accounts.map(a=><option key={a.code} value={a.code}>{a.code} · {a.name}</option>)}</select><input aria-label={'Debe apertura '+(i+1)} type="number" min="0" step="0.01" value={r.debit} onChange={e=>setRows(v=>v.map((x,j)=>j===i?{...x,debit:e.target.value}:x))}/><input aria-label={'Haber apertura '+(i+1)} type="number" min="0" step="0.01" value={r.credit} onChange={e=>setRows(v=>v.map((x,j)=>j===i?{...x,credit:e.target.value}:x))}/><button className="icon-button" title="Quitar fila" onClick={()=>setRows(v=>v.filter((_,j)=>j!==i))}><X size={14}/></button></div>)}</div><button className="text-button" onClick={()=>setRows(v=>[...v,{id:newId(),accountCode:'101.01',debit:'',credit:''}])}><Plus size={16}/>Agregar cuenta</button><div className="form-total"><span>Diferencia de apertura</span><strong className={valid?'':'red-text'}>{currency(debit.minus(credit).toFixed(2))}</strong></div><div className="modal-actions"><button className="button secondary" onClick={onClose}>Cancelar</button><button className="button primary" disabled={!valid||(kind==='adjustment'&&(!concept.trim()||!entryDate.startsWith(project.period)||debit.isZero()))} onClick={()=>onSave({id:existing?.id||newId(),date:kind==='opening'?project.period+'-01':entryDate,concept:kind==='opening'?'Asiento de apertura confirmado':concept,kind,sourceIds:[],lines:rows.map(r=>({...r,debit:r.debit||'0.00',credit:r.credit||'0.00'}))})}>{kind==='opening'?'Confirmar apertura':'Confirmar asiento'}</button></div></Modal>;
}
function AccountModal({accounts,onClose,onSave}:{accounts:Account[];onClose:()=>void;onSave:(a:Account)=>void}){const [code,setCode]=useState(''),[name,setName]=useState(''),[type,setType]=useState<Account['type']>('expense'),[nature,setNature]=useState<'debit'|'credit'>('debit');return <Modal title="Agregar cuenta" subtitle="La naturaleza y clasificación determinan su presentación en los reportes." onClose={onClose}><div className="form-grid"><label className="field"><span>Código</span><input value={code} onChange={e=>setCode(e.target.value)}/></label><label className="field"><span>Nombre</span><input value={name} onChange={e=>setName(e.target.value)}/></label><label className="field"><span>Clasificación</span><select value={type} onChange={e=>setType(e.target.value as typeof type)}>{Object.entries({asset:'Activo',liability:'Pasivo',equity:'Capital',income:'Ingreso',cost:'Costo',expense:'Gasto'}).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label className="field"><span>Naturaleza</span><select value={nature} onChange={e=>setNature(e.target.value as typeof nature)}><option value="debit">Deudora</option><option value="credit">Acreedora</option></select></label></div><div className="modal-actions"><button className="button primary" disabled={!code.trim()||!name.trim()||accounts.some(a=>a.code===code.trim())} onClick={()=>onSave({code:code.trim(),name:name.trim(),type,nature})}>Agregar cuenta</button></div></Modal>}
function AssetModal({project,onClose,onSave}:{project:Project;onClose:()=>void;onSave:(a:FixedAsset)=>void}){const [name,setName]=useState(''),[type,setType]=useState<'depreciation'|'amortization'>('depreciation'),[cost,setCost]=useState(''),[residual,setResidual]=useState('0'),[months,setMonths]=useState('60'),[date,setDate]=useState(project.period+'-01');return <Modal title="Registrar activo" subtitle="Método lineal contable. Confirma por separado adquisición, vida útil y tratamiento fiscal." onClose={onClose}><div className="form-grid"><label className="field span-two"><span>Descripción</span><input value={name} onChange={e=>setName(e.target.value)}/></label><label className="field"><span>Tratamiento</span><select value={type} onChange={e=>setType(e.target.value as typeof type)}><option value="depreciation">Depreciación</option><option value="amortization">Amortización</option></select></label><label className="field"><span>Fecha de inicio de uso</span><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label className="field"><span>Costo sin IVA</span><input type="number" min="0" value={cost} onChange={e=>setCost(e.target.value)}/></label><label className="field"><span>Valor residual</span><input type="number" min="0" value={residual} onChange={e=>setResidual(e.target.value)}/></label><label className="field"><span>Vida útil en meses</span><input type="number" min="1" value={months} onChange={e=>setMonths(e.target.value)}/></label></div><div className="modal-actions"><button className="button primary" disabled={!name.trim()||Number(cost)<=0||Number(months)<=0||Number(residual)>Number(cost)} onClick={()=>onSave({id:newId(),name:name.trim(),type,cost,residual,usefulLifeMonths:Number(months),startDate:date,accountCode:type==='amortization'?'170.01':'150.01',expenseAccountCode:'603.01'})}>Confirmar activo</button></div></Modal>}
function LotModal({project,onClose,onSave}:{project:Project;onClose:()=>void;onSave:(a:Project['inventoryInitial'][0])=>void}){const [product,setProduct]=useState(''),[qty,setQty]=useState(''),[cost,setCost]=useState('');return <Modal title="Inventario inicial" subtitle="Registra cada capa de costo por separado. Su valor debe estar incluido en la cuenta de almacén de la apertura." onClose={onClose}><label className="field"><span>Artículo / clave</span><input value={product} onChange={e=>setProduct(e.target.value)}/></label><div className="form-grid"><label className="field"><span>Cantidad</span><input type="number" min="0" step="any" value={qty} onChange={e=>setQty(e.target.value)}/></label><label className="field"><span>Costo unitario sin IVA</span><input type="number" min="0" step="any" value={cost} onChange={e=>setCost(e.target.value)}/></label></div><div className="modal-actions"><button className="button primary" disabled={!product.trim()||Number(qty)<=0||!cost||Number(cost)<0} onClick={()=>onSave({id:newId(),productId:product.trim(),date:project.period+'-01',quantity:qty,unitCost:cost})}>Agregar existencias</button></div></Modal>}

function SettingsPanel({project,onChange,onEdit,onOpening,onAccount,onHistory,onDelete,onFlash,result}:{project:Project;onChange:(p:Project)=>void;onEdit:(f:(p:Project)=>Project,label?:string)=>void;onOpening:()=>void;onAccount:()=>void;onHistory:()=>void;onDelete:()=>void;onFlash:(t:string,e?:boolean)=>void;result:ProcessingResult}){
 const [deleteConfirm,setDeleteConfirm]=useState(false),[reopenReason,setReopenReason]=useState('');const tc=project.taxConfig as Project['taxConfig']&{priorPeriodConfirmed?:boolean;retentionsConfirmed?:boolean;vatRetentions?:string;fiscalAdjustments?:string};
 const field=(label:string,key:keyof Project['taxConfig'])=><label className="field" key={key}><span>{label}</span><input type="number" min="0" step="any" value={String(project.taxConfig[key]??'')} onChange={e=>onEdit(p=>({...p,taxConfig:{...p.taxConfig,[key]:e.target.value}}))}/></label>;
 return <><section className="panel panel-body"><h2>Datos del proyecto</h2><div className="form-grid"><label className="field"><span>Nombre</span><input value={project.name} disabled={project.closed} onChange={e=>onEdit(p=>({...p,name:e.target.value}))}/></label><label className="field"><span>RFC</span><input value={project.rfc} disabled={project.closed} placeholder="RFC del contribuyente" onChange={e=>onEdit(p=>({...p,rfc:e.target.value.toUpperCase()}))}/></label><label className="field"><span>Periodo</span><input type="month" min="2025-01" max="2026-12" value={project.period} disabled={project.closed} onChange={e=>onEdit(p=>({...p,period:e.target.value,ruleSetId:'mx-'+e.target.value.slice(0,4)+'-v1'}),'Cambiar periodo')}/></label><label className="field"><span>Método de registro</span><select value={project.inventorySystem} disabled={project.closed} onChange={e=>onEdit(p=>({...p,inventorySystem:e.target.value as Project['inventorySystem']}),'Cambiar método')}><option value="perpetual">Inventarios perpetuos</option><option value="analytical">Analítico</option></select></label><label className="field"><span>Valuación de inventarios</span><select value={project.valuation} disabled={project.closed} onChange={e=>onEdit(p=>({...p,valuation:e.target.value as Project['valuation']}),'Cambiar valuación')}><option value="fifo">PEPS</option><option value="average">Promedio móvil</option></select></label><label className="field"><span>Inventario final confirmado · analítico</span><input type="number" min="0" step="0.01" disabled={project.closed} value={project.taxConfig.finalInventory} placeholder="Requiere conteo y valuación" onChange={e=>onEdit(p=>({...p,taxConfig:{...p.taxConfig,finalInventory:e.target.value}}))}/></label></div><div className="button-group"><button className="button secondary" onClick={onOpening} disabled={project.closed}>Registrar apertura</button><button className="button secondary" onClick={onAccount} disabled={project.closed}>Agregar cuenta</button><button className="button secondary" onClick={onHistory}><History size={16}/>Historial</button></div></section>
 <section className="panel panel-body"><h2>Datos del papel de trabajo fiscal</h2><p className="small-note">Confirma la información previa. Una deducción o retención no se presume por ausencia de datos.</p><fieldset disabled={project.closed}><div className="form-grid">{field('Coeficiente de utilidad · persona moral','coefficient')}{field('ISR provisional pagado previamente','previousIsr')}{field('Ingresos acumulados de meses anteriores','priorTaxableIncome')}{field('Deducciones de meses anteriores','priorDeductions')}{field('Retenciones de ISR acumuladas','priorRetentions')}{field('IVA retenido al contribuyente · periodo','vatRetentions')}</div><label className="check-field"><input type="checkbox" checked={!!tc.priorPeriodConfirmed} onChange={e=>onEdit(p=>({...p,taxConfig:{...p.taxConfig,priorPeriodConfirmed:e.target.checked}}))}/><span>Verifiqué los acumulados y pagos de meses anteriores</span></label><label className="check-field"><input type="checkbox" checked={!!tc.retentionsConfirmed} onChange={e=>onEdit(p=>({...p,taxConfig:{...p.taxConfig,retentionsConfirmed:e.target.checked}}))}/><span>Revisé las retenciones de ISR e IVA aplicables</span></label></fieldset></section>
 <section className="panel panel-body"><h2>Cierre del periodo</h2><p className="small-note">El cierre conserva la versión de reglas y evita cambios hasta reabrirlo. Atiende las incidencias antes de confirmar.</p>{project.closed&&<label className="field reopen-reason"><span>Motivo de reapertura</span><input value={reopenReason} placeholder="Ej. Incorporar una factura pendiente" onChange={e=>setReopenReason(e.target.value)}/></label>}<div className="settings-row"><Status kind={project.closed?'success':'muted'}>{project.closed?'Periodo cerrado':'Periodo abierto'}</Status><button className="button secondary" onClick={()=>{try{onChange(project.closed?reopenProject(project,reopenReason):closeProject(project));onFlash(project.closed?'Periodo reabierto con historial.':'Periodo cerrado con la versión normativa del proyecto.');setReopenReason('');}catch(e){onFlash(e instanceof Error?e.message:String(e),true);}}}><LockKeyhole size={16}/>{project.closed?'Reabrir periodo':'Confirmar cierre'}</button></div></section>
 <section className="panel panel-body"><h2>Proyectos en este equipo</h2><p className="small-note">Antes de eliminar un proyecto, puedes descargar un respaldo desde Reportes.</p>{!deleteConfirm?<button className="button danger-button" onClick={()=>setDeleteConfirm(true)}><Trash2 size={15}/>Eliminar este proyecto</button>:<div className="button-group"><span>¿Eliminar “{project.name}” de este equipo?</span><button className="button danger-button" onClick={onDelete}>Sí, eliminar</button><button className="button secondary" onClick={()=>setDeleteConfirm(false)}>Cancelar</button></div>}</section></>;
}

function RulesPage(){
const sources=[
 {title:'Normas de Información Financiera 2026',tag:'Información financiera',detail:'Base de consulta autorizada del CINIF. Las reglas de ContaEZ son implementaciones propias; el libro no se redistribuye.',url:'https://cinif.org.mx/normatividad_NIF2026.php',date:'Edición 2026'},
 {title:'Aclaración editorial de NIF 2025',tag:'Erratas y vigencias',detail:'A-2, C-9 y C-20. A-2: vigencia para ejercicios que inician a partir del 1 de enero de 2026.',url:'https://cinif.org.mx/uploads/Libro_NIF_2025-Aclaracion_editorial.pdf',date:'28 mar 2025'},
 {title:'Promulgación y Mejoras 2026',tag:'Control de vigencia',detail:'Mejoras 2026 aplicables en 2026. Nuevas B-1 y B-3: vigentes desde 2028, con aplicación anticipada en 2027.',url:'https://www.cinif.org.mx/uploads/NIF_2026_Carta_PROMULGACION.pdf',date:'18 dic 2025'},
 {title:'Código Fiscal de la Federación',tag:'Legislación fiscal',detail:'Documentación soporte, contabilidad y comprobantes. Artículos 28, 29 y 29-A y reglamento aplicable.',url:'https://www.diputados.gob.mx/LeyesBiblio/pdf/CFF.pdf',date:'Reforma 9 abr 2026'},
 {title:'Ley del Impuesto sobre la Renta',tag:'ISR',detail:'Bases fiscales y obligaciones por régimen. El resultado contable se concilia con el tratamiento fiscal.',url:'https://www.diputados.gob.mx/LeyesBiblio/pdf/LISR.pdf',date:'Texto vigente'},
 {title:'Ley del Impuesto al Valor Agregado',tag:'IVA',detail:'Cobros, pagos, acreditamientos y retenciones. Los importes del XML se conservan como evidencia.',url:'https://www.diputados.gob.mx/LeyesBiblio/pdf/LIVA.pdf',date:'Texto vigente'},
 {title:'Cuarta modificación de la RMF 2026',tag:'Reglas administrativas',detail:'Incluye cambios en la regla 2.8.1.6 de contabilidad electrónica. Cada obligación requiere determinar su aplicabilidad.',url:'https://dof.gob.mx/nota_detalle.php?codigo=5802597&fecha=30/10/2026',date:'30 oct 2026'},
 {title:'Anexo 24 de la RMF 2026',tag:'Contabilidad electrónica',detail:'Catálogo, balanza, pólizas y auxiliares. La preparación del archivo se distingue de su presentación ante el SAT.',url:'https://www.sat.gob.mx/minisitio/NormatividadRMFyRGCE/documentos2026/rmf/anexos/Anexo_24_RMF2026-13012026.pdf',date:'13 ene 2026'},
 {title:'Anexo 20 · CFDI',tag:'Comprobantes fiscales',detail:'Importación de CFDI 4.0 y relación de facturas, notas de crédito y complementos de pago 2.0.',url:'https://wwwmat.sat.gob.mx/consultas/35025/formato-de-factura-electronica-(anexo-20)',date:'Versión aplicable'},
];
return <><PageTitle eyebrow="FUENTES Y ALCANCE" title="Hecha para México" subtitle="Normas contables y disposiciones fiscales, con funciones y vigencias diferentes."/><div className="normative-hero"><Landmark size={29}/><div><h2>La regla correcta para el ejercicio correcto.</h2><p>{DISCLAIMER}</p><span>Fuentes revisadas con corte al 12 de noviembre de 2026 · Consulta siempre las actualizaciones oficiales.</span></div></div><div className="coverage-grid"><section className="panel panel-body"><h3>Lo que automatiza esta versión</h3><p>Partida doble, inventarios PEPS y promedio, método analítico, activos lineales, conciliación y papeles de trabajo federales de los regímenes 601 y 612.</p></section><section className="panel panel-body"><h3>Lo que necesita datos o revisión adicional</h3><p>Juicios sobre provisiones, contingencias, deterioro y revelaciones; impuestos locales, regímenes distintos y marcos sectoriales requieren módulos específicos.</p></section></div><section className="panel source-list">{sources.map(s=><a href={s.url} target="_blank" rel="noreferrer" className="source-row" key={s.title}><span className="source-icon"><BookOpen size={19}/></span><div><span className="source-tag">{s.tag}</span><h3>{s.title}</h3><p>{s.detail}</p></div><span className="source-date">{s.date}<ArrowUpRight size={16}/></span></a>)}</section><div className="jurisdiction-note"><ShieldCheck size={18}/><p>Los proyectos conservan el paquete de reglas utilizado. Las actualizaciones normativas deben revisarse antes de recalcular periodos anteriores. Las propuestas de normas futuras no se aplican automáticamente.</p></div></>;
}
function App(){
 const [mode,setMode]=useState<'practice'|'business'|'individual'>('practice');
 return mode==='practice'?<StudentWorkspace onAccounting={setMode}/>:<AccountingWorkspace key={mode} initialMode={mode} onBack={()=>setMode('practice')}/>;
}
export default App;
